--
-- Table structure for table `orders`
--

DROP TABLE IF EXISTS `orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `orders` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `order_code` varchar(32) NOT NULL,
  `idempotency_key` varchar(100) DEFAULT NULL,
  `user_id` bigint unsigned NOT NULL,
  `status` enum('PENDING','CONFIRMED','PROCESSING','SHIPPED','DELIVERED','CANCELLED') NOT NULL DEFAULT 'PENDING',
  `payment_method` enum('COD','VNPAY','MOMO') NOT NULL DEFAULT 'COD',
  `shipping_method` enum('STANDARD','EXPRESS') NOT NULL DEFAULT 'STANDARD',
  `payment_status` enum('UNPAID','PAID','REFUNDED') NOT NULL DEFAULT 'UNPAID',
  `recipient_name` varchar(120) NOT NULL,
  `phone` varchar(30) NOT NULL,
  `shipping_address` json NOT NULL,
  `customer_note` varchar(1000) DEFAULT NULL,
  `coupon_code` varchar(40) DEFAULT NULL,
  `subtotal` decimal(12,2) NOT NULL,
  `discount_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `shipping_fee` decimal(12,2) NOT NULL DEFAULT '0.00',
  `total_amount` decimal(12,2) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `shipping_carrier` varchar(100) DEFAULT NULL,
  `tracking_number` varchar(100) DEFAULT NULL,
  `is_simulated` tinyint(1) NOT NULL DEFAULT '0',
  `shipper_user_id` bigint unsigned DEFAULT NULL,
  `delivered_at` datetime DEFAULT NULL,
  `received_confirmed_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_orders_code` (`order_code`),
  UNIQUE KEY `uq_orders_user_idempotency` (`user_id`,`idempotency_key`),
  KEY `idx_orders_user_created` (`user_id`,`created_at`),
  KEY `idx_orders_status_created` (`status`,`created_at`),
  KEY `idx_orders_shipper_status` (`shipper_user_id`,`status`,`created_at`),
  CONSTRAINT `fk_orders_shipper` FOREIGN KEY (`shipper_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_orders_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2066 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

