--
-- Table structure for table `payment_checkouts`
--

DROP TABLE IF EXISTS `payment_checkouts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payment_checkouts` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `idempotency_key` varchar(100) NOT NULL,
  `reference` varchar(100) NOT NULL,
  `amount` decimal(12,2) NOT NULL,
  `checkout_snapshot` json NOT NULL,
  `status` varchar(16) NOT NULL DEFAULT 'PENDING',
  `order_id` bigint unsigned DEFAULT NULL,
  `provider_transaction_id` varchar(100) DEFAULT NULL,
  `provider_response_code` varchar(20) DEFAULT NULL,
  `expires_at` datetime NOT NULL,
  `confirmed_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_payment_checkout_request` (`user_id`,`idempotency_key`),
  UNIQUE KEY `uq_payment_checkout_reference` (`reference`),
  UNIQUE KEY `uq_payment_checkout_order` (`order_id`),
  CONSTRAINT `fk_payment_checkout_order` FOREIGN KEY (`order_id`) REFERENCES `orders` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_payment_checkout_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
