  `status` enum('ACTIVE','INACTIVE') NOT NULL DEFAULT 'ACTIVE',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `occasion_tags` json DEFAULT NULL,
  `recipient_tags` json DEFAULT NULL,
  `interest_tags` json DEFAULT NULL,
  `style` varchar(80) DEFAULT NULL,
  `gift_type` varchar(80) DEFAULT NULL,
  `is_featured` tinyint(1) NOT NULL DEFAULT '0',
  `ml_product_id` bigint unsigned DEFAULT NULL,
  `is_synthetic_display` tinyint(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `ml_product_id` (`ml_product_id`),
  KEY `fk_products_category` (`category_id`),
  CONSTRAINT `fk_products_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE SET NULL
